        if not any(v == fg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v == fg for v in grid[r]):
            r += 1
        bands.append((start, r))
    if len(bands) < 2:
        return [row[:] for row in grid]
    (a0, a1), (b0, b1) = bands[0], bands[1]
    if a1 - a0 != b1 - b0:
        return [row[:] for row in grid]
    nrows = a1 - a0

    # Find the horizontal displacement mapping panel A columns to panel B.
    best_d, best_score = 0, -1.0
    for d in range(-min(8, w - 1), min(8, w - 1) + 1):
        same = total = 0
        for dy in range(nrows):
            for x in range(w):
                z = x + d
                if 0 <= z < w:
                    same += ((grid[a0 + dy][x] == fg) == (grid[b0 + dy][z] == fg))
                    total += 1
        score = same / total if total else 0
        if score > best_score:
            best_d, best_score = d, score

    count_a = sum(grid[y][x] == fg for y in range(a0, a1) for x in range(w))
    count_b = sum(grid[y][x] == fg for y in range(b0, b1) for x in range(w))
    if count_a > count_b:
        src0, dst0, shift = a0, b0, best_d
    else:
        src0, dst0, shift = b0, a0, -best_d

    out = [row[:] for row in grid]
