        dst_y = dst0 + dy
        rightmost = max((x for x in range(w) if grid[dst_y][x] == fg), default=-1)
        for x in range(w):
            z = x + shift
            if 0 <= z < w and z > rightmost and grid[src0 + dy][x] == fg and grid[dst_y][z] == bg:
                out[dst_y][z] = 1
    return out

